#!/usr/bin/env Rscript
# ---------------------------------------------------------------------------
# data-raw/pilar8_real_pedons.R
#
# Pillar 8 on measured pedons, not on profiles generated by Pillar 2.
#
# WHAT THE PAPER SAID, AND WHY IT WAS WRONG TWICE. The manuscript first
# claimed "no real multi-horizon depth data ships with the package", which is
# false: 5,853 measured horizons over 1,105 WoSIS profiles do. Corrected, it
# then said refitting needed "a trunk that accepts ragged depth supports" --
# also wrong. The trunk already takes arbitrary query depths; `predict()` has
# a `newdepths` argument and always did. The obstacle was the TRAINING layout:
# `no_deeponet_fit()` wants a rectangular `targets` matrix over one shared
# depth vector, and real pedons carry four to thirty-one horizons at
# irregular boundaries.
#
# THE FIX WAS A MASKED LOSS, not a new architecture. NA in `targets` now marks
# a depth node an observation does not constrain; the residual is zeroed there
# and every denominator counts observed cells. Both backends implement it.
#
# THE DEPTH NODES ARE NOT INTERPOLATION. A horizon SPANS a depth, so the value
# at 30 cm for a pedon whose horizon runs 25-45 cm is a measured laboratory
# value, not something interpolated between horizons. A node is observed when
# some horizon spans it and missing otherwise. On this archive that gives a
# matrix about three-quarters filled, against 2.5% for the union of all
# distinct horizon mid-depths -- which is why standard nodes are used.
#
# EVALUATION is spatially blocked with a buffer, the same design the
# cross-pillar benchmark uses, and the operator is scored against the same
# zero-parameter baselines Pillar 2 is scored against.
#
# Output: inst/extdata/pilar8_real_pedons.rds
# ---------------------------------------------------------------------------

suppressMessages(pkgload::load_all(".", quiet = TRUE))
set.seed(31L)

NODES <- c(5, 15, 30, 60, 100, 150, 200)

D <- readRDS("inst/extdata/piml_wosis_cerrado.rds")
H <- D$horizons
P <- D$profiles

# --- targets on standard nodes, NA where no horizon spans the node ----------
prof <- split(H, H$profile_id)
prof <- prof[vapply(prof, nrow, 0L) >= 4L]
value_at <- function(s, z) {
  i <- which(s$top <= z & s$bottom > z)
  if (!length(i)) return(NA_real_)
  s$soc_g_kg[i[1]]
}
TG <- t(vapply(prof, function(s) {
  s <- s[order(s$top), ]
  vapply(NODES, function(z) value_at(s, z), numeric(1))
}, numeric(length(NODES))))
colnames(TG) <- paste0("z", NODES)

keep <- rowSums(is.finite(TG)) >= 3L
TG <- TG[keep, , drop = FALSE]
ids <- names(prof)[keep]
message(sprintf("%d profiles with >= 3 observed nodes of %d", nrow(TG), length(NODES)))
message(sprintf("  target matrix %.0f%% observed", 100 * mean(is.finite(TG))))

# --- covariates, matched to the nearest causal-extract profile -------------
CV <- readRDS("inst/extdata/causal_cerrado_real_v2.rds")$profiles
xy <- P[match(ids, P$profile_id), c("x", "y")]
nn <- vapply(seq_len(nrow(xy)), function(i)
  which.min((CV$lon - xy$x[i])^2 + (CV$lat - xy$y[i])^2), integer(1))
d_km <- vapply(seq_len(nrow(xy)), function(i)
  edaphos:::.gc_km(cbind(xy$x[i], xy$y[i]),
                   cbind(CV$lon[nn[i]], CV$lat[nn[i]]))[1, 1], numeric(1))
COVS <- c("mat", "map", "elev", "slope", "clay", "sand")
X <- as.matrix(CV[nn, COVS])
ok <- stats::complete.cases(X) & d_km <= 5
message(sprintf("  %d of %d have a covariate match within 5 km", sum(ok), length(ok)))
TG <- TG[ok, , drop = FALSE]; X <- X[ok, , drop = FALSE]
ids <- ids[ok]; xy <- xy[ok, ]

# --- spatially blocked folds -----------------------------------------------
SF <- spatial_block_folds(as.matrix(xy), k = 5L, buffer_km = 20, seed = 31L)
message(sprintf("%d folds over %d profiles; %d buffered out",
                length(SF$test), nrow(TG), sum(SF$n_buffered)))

rows <- list()
for (fd in seq_along(SF$test)) {
  tr <- SF$train[[fd]]; te <- SF$test[[fd]]
  if (length(tr) < 40L || length(te) < 5L) next
  fit <- tryCatch(
    no_deeponet_fit(NODES, TG[tr, , drop = FALSE], X[tr, , drop = FALSE],
                    epochs = 400L, seed = 31L),
    error = function(e) { message("  fold ", fd, ": ", conditionMessage(e)); NULL })
  if (is.null(fit)) next
  pred <- predict(fit, X[te, , drop = FALSE])
  obs  <- TG[te, , drop = FALSE]
  m <- is.finite(obs)
  # Baselines scored on exactly the same cells: the training-set mean at each
  # node (the achievable null), and each profile's own shallowest observed
  # value carried down (what a practitioner does with one sample).
  node_mean <- colMeans(TG[tr, , drop = FALSE], na.rm = TRUE)
  top_carry <- apply(obs, 1L, function(r) { k <- which(is.finite(r)); if (!length(k)) NA_real_ else r[k[1]] })
  rows[[length(rows) + 1L]] <- data.frame(
    fold = fd,
    obs  = obs[m],
    deeponet = pred[m],
    node_mean = matrix(rep(node_mean, each = nrow(obs)), nrow(obs))[m],
    top_carry = matrix(rep(top_carry, times = ncol(obs)), nrow(obs))[m],
    node = matrix(rep(NODES, each = nrow(obs)), nrow(obs))[m],
    stringsAsFactors = FALSE)
}
R <- do.call(rbind, rows)

sc <- function(p, o) c(RMSE = sqrt(mean((p - o)^2)), MAE = mean(abs(p - o)))
M <- list(`DeepONet (real pedons)` = R$deeponet,
          `training-set node mean` = R$node_mean,
          `carry the shallowest value down` = R$top_carry)
tab <- do.call(rbind, lapply(names(M), function(nm) {
  v <- sc(M[[nm]], R$obs)
  data.frame(method = nm, n = nrow(R), RMSE = v[["RMSE"]], MAE = v[["MAE"]],
             stringsAsFactors = FALSE)
}))
null_rmse <- tab$RMSE[tab$method == "training-set node mean"]
tab$skill <- 1 - (tab$RMSE / null_rmse)^2
tab <- tab[order(tab$RMSE), ]

cat(sprintf("\n=== Pillar 8 on %d measured cells, %d profiles, blocked folds ===\n",
            nrow(R), nrow(TG)))
for (i in seq_len(nrow(tab)))
  cat(sprintf("  %-34s RMSE %6.3f  MAE %6.3f  skill %+.3f\n",
              tab$method[i], tab$RMSE[i], tab$MAE[i], tab$skill[i]))

by_node <- do.call(rbind, lapply(sort(unique(R$node)), function(z) {
  x <- R[R$node == z, ]
  data.frame(node = z, n = nrow(x),
             rmse_deeponet = sqrt(mean((x$deeponet - x$obs)^2)),
             rmse_mean = sqrt(mean((x$node_mean - x$obs)^2)),
             stringsAsFactors = FALSE)
}))
cat("\nby depth node:\n"); print(by_node, row.names = FALSE, digits = 3)

saveRDS(list(
             # Binds this bundle to the script that made it: see R/provenance.R.
             provenance = edaphos_provenance(),
             cv = R, table = tab, by_node = by_node, nodes = NODES,
             n_profiles = nrow(TG), n_cells = nrow(R),
             frac_observed = mean(is.finite(TG)),
             covariates = COVS, buffer_km = 20,
             built_by = "data-raw/pilar8_real_pedons.R"),
        "inst/extdata/pilar8_real_pedons.rds")
message("\nwrote inst/extdata/pilar8_real_pedons.rds")
